        <template v-if="v.detail.kind==='candidates'&&v.detail.row.eligible"><el-button @click="v.editorMode=v.editorMode==='publish'?'':'publish'">明确发布为知识版本</el-button><fieldset v-if="v.editorMode==='publish'"><legend>显式知识发布，不建立临床规则或启用功能</legend><el-input v-for="[key,label] in knowledgeFields" :key="key" v-model="v.knowledgeForm[key]" :aria-label="label" :placeholder="label" :type="key==='basis_note'?'textarea':'text'" /><el-select v-model="v.knowledgeForm.category" aria-label="知识类别"><el-option v-for="(label,value) in categories" :key="value" :label="label" :value="value" /></el-select><el-select v-model="v.knowledgeForm.feature_keys" aria-label="知识适用功能" multiple filterable><el-option v-for="item in v.options.knowledge_features" :key="item.key" :label="item.name" :value="item.key" /></el-select><el-button type="primary" :loading="v.busy" @click="v.mutate('publish')">显式发布完整引文</el-button></fieldset></template>
        <fieldset v-if="v.detail.row.governance.status!=='revoked'"><legend>撤销本件</legend><p>保留原文与原签署，使依赖本件的知识失去使用资格。</p><el-input v-model="v.revokeNote" aria-label="撤销依据" type="textarea" /><el-button type="danger" :loading="v.busy" @click="v.mutate('revoke')">按当前版本撤销</el-button></fieldset><p v-if="v.formError" role="alert">{{ v.formError }}</p>
      </template><template #footer><el-button @click="v.detailOpen=false">关闭原件核对</el-button></template>
    </el-dialog>
  </section>
</template>
<script setup>
import {reactive} from 'vue';
import {useDocumentEvidence} from './useDocumentEvidence';
const props=defineProps({active:{type:Boolean,default:true}}),emit=defineEmits(['knowledge-published']),v=reactive(useDocumentEvidence(props,emit));
const originalFields=[['title','原文标题'],['version','提交方声明的版本'],['declared_source_uri','声明出处（仅保存，不访问外部地址）'],['declared_publisher','声明发布方（未记录留空）'],['source_available_at','原可得UTC（未记录留空）'],['applicability_note','适用范围原说明'],['authorization_note','授权使用说明']],knowledgeFields=[['title','知识标题'],['version','知识版本'],['department_id','知识科室ID（可选）'],['effective_from','知识生效UTC（仅整秒，可选）'],['effective_to','知识失效UTC（仅整秒，可选）'],['basis_note','知识发布依据']],categories={clinical:'临床知识',drug:'药品资料',hospital:'院内服务',operations:'运维',training:'模拟培训'},knowledgeStates={published:'已发布',retired:'已停用',draft:'草稿'},reviewLabels={unknown:'未审核',confirmed:'已明确确认',not_confirmed:'未确认'},reasonLabels={original_not_published:'原文尚未发布或已撤销',original_not_current:'原文或原审核版本已失效',candidate_not_approved:'条款候选未批准或已失效',publication_revoked:'知识发布件已撤销',knowledge_not_published:'真实知识已停用或未发布',knowledge_changed:'真实知识内容或元数据已改变'};
</script>
<style scoped>
.document-evidence{min-width:0}.el-alert{margin-bottom:12px}.el-select,.el-input{margin:6px 0;width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:45vh;overflow:auto;border:1px solid #dcdfe6;padding:12px}code{overflow-wrap:anywhere}fieldset{border:1px solid #dcdfe6;padding:12px;margin:12px 0}[role=alert]{color:#b42318}.el-pagination{margin-top:12px}
</style>
